DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_1','Viltrum[NEWLINE]Conquest momentum with an unavoidable biological crisis[NEWLINE]Domination; rebuild before pursuing a conventional fallback[NEWLINE][NEWLINE]Turn first foreign conquests into momentum while preparing a state that can survive the Scourge. The elite Warrior is a timing opportunity and a crisis trigger; reaching its technology is not the end of the campaign''s planning.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_2','Develop a productive economy, garrisons and a conventional army. Choose early conquests for lasting value, not recapture farming. Growth and Happiness matter because the later biological crisis will damage both population and military capacity.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_3','Use first-conquest Momentum to support a coherent campaign. Before the Warrior and outbreak timing, build recovery infrastructure, retain conventional Auxiliaries and avoid making every front depend on Bloodline survivors.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_4','Choose Quarantine or Crusade with the current army, food, treasury and enemy pressure in mind. Defend the weak survivors, respect the restrictions of the selected phase, and rebuild production before attempting another long offensive.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_5','- First conquests can reinforce military Production and experience.[NEWLINE]- Elite Warriors provide powerful late operational tools.[NEWLINE]- Garrisons and support infrastructure contribute to occupation and recovery.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_6','- The Scourge is guaranteed and cannot be solved by avoiding one optional panel.[NEWLINE]- Both crisis routes impose severe population and economic losses.[NEWLINE]- Kills, conquests and returns have attribution and once-per-city limits; they are not free farms.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_7','- Avoid feeding a chain of undefended first conquests.[NEWLINE]- Prepare pressure for the actual crisis and recovery phase rather than meeting the elite army at its strongest moment.[NEWLINE]- Force several defensive commitments when production, population and survivors are weakest.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_8','- Assuming the Scourge can be skipped by delaying the first Warrior indefinitely.[NEWLINE]- Leaving every defensive duty to Bloodline units.[NEWLINE]- Choosing Crusade without enough targets, reserves and safe healing for its survivors.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: A well-timed conquest can punish expensive, lightly defended research and Wonder cities.[NEWLINE][NEWLINE]RomanGladius Network: Large Servers are valuable targets when their owner has invested in population and staffing rather than a unified defense.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A stocked, positioned melee army can exploit the severe Scourge vulnerability window.[NEWLINE][NEWLINE]The Threshold Court: A maintained House network can reinforce remote cities and make a clean first-conquest chain harder to achieve.');
