INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_BACKGROUND','Turn first foreign conquests into momentum while preparing a state that can survive the Scourge. The elite Warrior is a timing opportunity and a crisis trigger; reaching its technology is not the end of the campaign''s planning.');
