INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_LEADER_BACKGROUND','Turn first foreign conquests into momentum while preparing a state that can survive the Scourge. The elite Warrior is a timing opportunity and a crisis trigger; reaching its technology is not the end of the campaign''s planning.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_VILTRUM_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_STRATEGY','Turn first foreign conquests into momentum while preparing a state that can survive the Scourge. The elite Warrior is a timing opportunity and a crisis trigger; reaching its technology is not the end of the campaign''s planning.[NEWLINE][NEWLINE]Develop a productive economy, garrisons and a conventional army. Choose early conquests for lasting value, not recapture farming. Growth and Happiness matter because the later biological crisis will damage both population and military capacity.[NEWLINE][NEWLINE]Use first-conquest Momentum to support a coherent campaign. Before the Warrior and outbreak timing, build recovery infrastructure, retain conventional Auxiliaries and avoid making every front depend on Bloodline survivors.[NEWLINE][NEWLINE]Choose Quarantine or Crusade with the current army, food, treasury and enemy pressure in mind. Defend the weak survivors, respect the restrictions of the selected phase, and rebuild production before attempting another long offensive.');
