INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_LEADER_TEXT_2','Develop a productive economy, garrisons and a conventional army. Choose early conquests for lasting value, not recapture farming. Growth and Happiness matter because the later biological crisis will damage both population and military capacity.[NEWLINE][NEWLINE]Use first-conquest Momentum to support a coherent campaign. Before the Warrior and outbreak timing, build recovery infrastructure, retain conventional Auxiliaries and avoid making every front depend on Bloodline survivors.[NEWLINE][NEWLINE]Choose Quarantine or Crusade with the current army, food, treasury and enemy pressure in mind. Defend the weak survivors, respect the restrictions of the selected phase, and rebuild production before attempting another long offensive.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_VILTRUMEMPIRE_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Sol Intellect: A well-timed conquest can punish expensive, lightly defended research and Wonder cities.[NEWLINE][NEWLINE]RomanGladius Network: Large Servers are valuable targets when their owner has invested in population and staffing rather than a unified defense.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A stocked, positioned melee army can exploit the severe Scourge vulnerability window.[NEWLINE][NEWLINE]The Threshold Court: A maintained House network can reinforce remote cities and make a clean first-conquest chain harder to achieve.');
